60: export function getCookie(name: string): string | undefined {
61:   const value = '; ' + document.cookie;
62:   const parts = value.split('; ' + name + '=');
63:   if (parts.length == 2) {
64:     return parts.pop()?.split(';').shift();
65:   }
66:   return undefined;
67: }

