45: export function setCookie(name: string, val: string) {
46:   const date = new Date();
47:   date.setTime(date.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 días
48:   document.cookie = `${name}=${val}; expires=${date.toUTCString()}; path=/`;
49: }
50: 
51: export function getCookie(name: string): string | undefined {
52:   const value = '; ' + document.cookie;
53:   const parts = value.split('; ' + name + '=');
54:   if (parts.length == 2) {
55:     return parts.pop()?.split(';').shift();
56:   }
57:   return undefined;
58: }

