43: function getCookie(name: string): string | undefined {
44:   const value = `; ${document.cookie}`;
45:   const parts = value.split(`; ${name}=`);
46: 
47:   if (parts.length === 2) {
48:     return parts.pop()?.split(';').shift();
49:   }
50: 
51:   return undefined;
52: }

